source=re.sub(r'<main\b[^>]*>.*?</main>',lambda m:'<main>'+body+'</main>',source,count=1,flags=re.S)
source=re.sub(r'<header class="article-hero">.*?</header>','<header class="article-hero"><div class="brand">NEXALYPLANNER JOURNAL</div><h1>Small Business Balance Sheet Template With a Filled Example</h1><p>Draft resource · Prepared October 23, 2026</p></header>',source,count=1,flags=re.S)
